def fix(s):
    b = bytearray(s.encode('latin1'))
    i = 0
    out = bytearray()
    while i < len(b):
        c = b[i]
        if c < 0x80:
            out.append(c)
            i += 1
        elif 0xC0 <= c < 0xE0:
            n = 1
        elif 0xE0 <= c < 0xF0:
            n = 2
        elif 0xF0 <= c < 0xF8:
            n = 3
        else:
            out.append(c)
            i += 1
            continue
        # need n continuation bytes
        seq = bytearray([c])
        ok = True
        for k in range(1, n+1):
            if i+k >= len(b):
                ok = False
                break
            cb = b[i+k]
            if cb == 0x20:
                cb = 0xA0  # restore likely nbsp->space corruption
            if not (0x80 <= cb < 0xC0):
                ok = False
                break
            seq.append(cb)
        if ok:
            out.extend(seq)
            i += n+1
        else:
            out.append(c)
            i += 1
    return bytes(out)

